	}
}
' > dbg/main.go && cd dbg && go mod init dbg >/dev/null 2>&1; go run .

python3 - <<'EOF'
import re
src = open('dbg/solver.go').read()
# trace entry/exit of solve
src = src.replace('''	solve = func(col, carry int) bool {
		if col == maxLen {
			return carry == 0
		}''', '''	solve = func(col, carry int) bool {
		defer func() { fmt.Println("  solve col", col, "carry", carry, "assign:", assign) }()
